#define GetNtMajorVersion()        \
  __extension__({                  \
    uintptr_t __x;                 \
    __asm__("mov\t%%gs:96,%q0\r\n" \
            "mov\t280(%q0),%b0"    \
            : "=q"(__x));          \
    (unsigned char)__x;            \
  })
